void Reverse(LinkList *L) {
    LNode *p = L->next;    // p指向第一个结点
    L->next = NULL;        // 头结点的next置空
    LNode *q;
    while (p != NULL) {
        q = p->next;       // q保存p的后继
        p->next = L->next; // 将p插入到头结点之后
        L->next = p;
        p = q;             // p指向下一个待处理结点
    }
}
