LinkList Merge(LinkList La, LinkList Lb) {
    LNode *pa = La->next, *pb = Lb->next;
    LinkList Lc = La;           // 用La的头结点作为Lc的头结点
    LNode *pc = Lc;

    while (pa != NULL && pb != NULL) {
        if (pa->data <= pb->data) {
            pc->next = pa;
            pc = pa;
            pa = pa->next;
        } else {
            pc->next = pb;
            pc = pb;
            pb = pb->next;
        }
    }
    pc->next = (pa != NULL) ? pa : pb;  // 处理剩余部分
    free(Lb);  // 释放Lb的头结点
    return Lc;
}
