void Push(SqStack *S, char x) { S->data[++S->top] = x; }
char Pop(SqStack *S) { return S->data[S->top--]; }
char GetTop(SqStack S) { return S.data[S.top]; }

int IsMatch(char *s) {
    SqStack S;
    InitStack(&S);
    char c;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == '(' || s[i] == '[' || s[i] == '{') {
            Push(&S, s[i]);
        } else if (s[i] == ')' || s[i] == ']' || s[i] == '}') {
            if (IsEmpty(S)) return 0;
            c = GetTop(S);
            if ((s[i] == ')' && c == '(') ||
                (s[i] == ']' && c == '[') ||
                (s[i] == '}' && c == '{')) {
                Pop(&S);
            } else {
                return 0;
            }
        }
    }
    return IsEmpty(S);
}
