int Evaluate(char *exp) {
    int numStack[100], numTop = -1;
    char opStack[100], opTop = -1;

    int priority(char c) {
        if (c == '+' || c == '-') return 1;
        if (c == '*' || c == '/') return 2;
        return 0;
    }

    void calc() {
        int b = numStack[numTop--];
        int a = numStack[numTop--];
        char op = opStack[opTop--];
        switch(op) {
            case '+': numStack[++numTop] = a + b; break;
            case '-': numStack[++numTop] = a - b; break;
            case '*': numStack[++numTop] = a * b; break;
            case '/': numStack[++numTop] = a / b; break;
        }
    }

    for (int i = 0; exp[i] != '\0'; i++) {
        if (exp[i] >= '0' && exp[i] <= '9') {
            int num = 0;
            while (exp[i] >= '0' && exp[i] <= '9') {
                num = num * 10 + exp[i] - '0';
                i++;
            }
            numStack[++numTop] = num;
            i--;
        } else if (exp[i] == '+' || exp[i] == '-' || 
                   exp[i] == '*' || exp[i] == '/') {
            while (opTop >= 0 && priority(opStack[opTop]) >= priority(exp[i])) {
                calc();
            }
            opStack[++opTop] = exp[i];
        }
    }
    while (opTop >= 0) calc();
    return numStack[numTop];
}
