void LevelOrder(BiTree T) {
    if (T == NULL) return;

    BiTree queue[100];
    int front = 0, rear = 0;
    queue[rear++] = T;  // 根结点入队

    while (front < rear) {
        BiTree p = queue[front++];  // 出队
        visit(p);
        if (p->lchild != NULL)
            queue[rear++] = p->lchild;  // 左孩子入队
        if (p->rchild != NULL)
            queue[rear++] = p->rchild;  // 右孩子入队
    }
}
