BiTree CreateBT(char *pre, char *in, int n) {
    if (n <= 0) return NULL;

    BiTree root = (BiTree)malloc(sizeof(BiTNode));
    root->data = pre[0];  // 先序第一个元素是根

    int i;
    for (i = 0; i < n; i++) {
        if (in[i] == pre[0]) break;  // 在中序中找根
    }

    // 递归构造左子树
    root->lchild = CreateBT(pre + 1, in, i);
    // 递归构造右子树
    root->rchild = CreateBT(pre + i + 1, in + i + 1, n - i - 1);

    return root;
}
