int visited[MAX_VERTEX_NUM];

void BFS(ALGraph G, int v) {
    int queue[MAX_VERTEX_NUM];
    int front = 0, rear = 0;

    visited[v] = 1;
    visit(v);
    queue[rear++] = v;  // 起始顶点入队

    while (front < rear) {
        int u = queue[front++];  // 出队
        ArcNode *p = G.vertices[u].firstarc;
        while (p != NULL) {
            int w = p->adjvex;
            if (!visited[w]) {
                visited[w] = 1;
                visit(w);
                queue[rear++] = w;  // 入队
            }
            p = p->nextarc;
        }
    }
}
