int BinarySearch(int A[], int n, int key) {
    int low = 0, high = n - 1, mid;
    while (low <= high) {
        mid = (low + high) / 2;
        if (A[mid] == key)
            return mid;        // 查找成功
        else if (A[mid] > key)
            high = mid - 1;    // 在左半区查找
        else
            low = mid + 1;     // 在右半区查找
    }
    return -1;  // 查找失败
}
