void InsertSort(int A[], int n) {
    int i, j, temp;
    for (i = 1; i < n; i++) {
        if (A[i] < A[i-1]) {  // 需要插入
            temp = A[i];       // 保存待插入元素
            for (j = i-1; j >= 0 && A[j] > temp; j--) {
                A[j+1] = A[j];  // 元素后移
            }
            A[j+1] = temp;     // 插入到正确位置
        }
    }
}
