void SelectSort(int A[], int n) {
    int i, j, min, temp;
    for (i = 0; i < n-1; i++) {
        min = i;  // 记录最小元素位置
        for (j = i+1; j < n; j++) {
            if (A[j] < A[min])
                min = j;
        }
        if (min != i) {  // 交换
            temp = A[i];
            A[i] = A[min];
            A[min] = temp;
        }
    }
}
