void AdjustDown(int A[], int k, int n) {
    // 将以k为根的子树调整为堆
    A[0] = A[k];  // A[0]暂存根结点
    for (int i = 2*k; i <= n; i *= 2) {
        if (i < n && A[i] < A[i+1])  // 取较大孩子
            i++;
        if (A[0] >= A[i]) break;     // 筛选结束
        A[k] = A[i];                 // 孩子上移
        k = i;
    }
    A[k] = A[0];  // 根结点放入最终位置
}

void BuildMaxHeap(int A[], int n) {
    // 建立大根堆
    for (int i = n/2; i >= 1; i--)
        AdjustDown(A, i, n);
}

void HeapSort(int A[], int n) {
    BuildMaxHeap(A, n);  // 建堆
    for (int i = n; i > 1; i--) {
        // 将堆顶元素与堆底元素交换
        int temp = A[1];
        A[1] = A[i];
        A[i] = temp;
        AdjustDown(A, 1, i-1);  // 调整剩余元素为堆
    }
}
